// src/components/StatsBar.js
// Barre de statistiques horizontale avec indicateurs visuels — pas de rectangles génériques

export default function StatsBar({ stats }) {
  // stats = [{ label, value, total, color, format }]
  return (
    <div style={{
      display: "flex", gap: 0,
      background: "var(--surface)", border: "1px solid var(--border)",
      borderRadius: "var(--radius-lg)", overflow: "hidden",
      marginBottom: 28,
    }}>
      {stats.map((s, i) => {
        const pct = s.total ? Math.round((s.value / s.total) * 100) : null;
        const isLast = i === stats.length - 1;
        return (
          <div key={s.label} style={{
            flex: 1, padding: "18px 22px",
            borderRight: isLast ? "none" : "1px solid var(--border)",
            position: "relative", overflow: "hidden",
          }}>
            {/* Barre de progression en fond */}
            {pct !== null && (
              <div style={{
                position: "absolute", bottom: 0, left: 0,
                height: 3, width: `${pct}%`,
                background: s.color || "var(--accent)",
                borderRadius: "0 2px 0 0",
                transition: "width 0.6s ease",
              }} />
            )}

            <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.07em", marginBottom: 8 }}>
              {s.label}
            </div>

            <div style={{ display: "flex", alignItems: "baseline", gap: 6 }}>
              <span style={{ fontSize: 26, fontWeight: 600, color: s.color || "var(--text)", letterSpacing: "-0.5px", lineHeight: 1 }}>
                {s.value}
              </span>
              {s.total !== undefined && s.total !== s.value && (
                <span style={{ fontSize: 13, color: "var(--muted)", fontFamily: "'DM Mono', monospace" }}>
                  / {s.total}
                </span>
              )}
              {pct !== null && pct > 0 && (
                <span style={{ fontSize: 11, color: s.color || "var(--muted)", marginLeft: 4, opacity: 0.7 }}>
                  {pct}%
                </span>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}
